        total_charges = PaymentTableSelectors.get_total_of_charges_table()

        # Validate credit_table_lines is a list (consistent with previous turn)
        if not isinstance(credit_table_lines, list):
            print(f"Error: credit_table_lines must be a list, got {type(credit_table_lines)}")
            return StepResponse(result=ResultType.FAILURE)

        # Process each item with same validation as previous turn
        remaining_balance = float(total_charges)
        updated_credits = []
