%% MATLAB Implementation for Fourier Domain Restoration with Discussion

%% 1. Wiener Filter Implementation
function restored = wiener_fourier_restoration(y, noise_var, signal_var)
    y_double = im2double(y);
    Y = fft2(y_double);

    % Estimate degradation function (modify based on your specific degradation)
    [M,N] = size(Y);
    H_est = ones(M,N);  % Start with identity

    % Identify corrupted frequencies (modify for your specific case)
    Y_shifted = fftshift(Y);
    magnitude = abs(Y_shifted);
    threshold = 10*median(magnitude(:));
    [rows,cols] = find(magnitude > threshold);

    % Apply Wiener filter in frequency domain
    H_conj = conj(H_est);
    H_mag_sq = abs(H_est).^2;
    NSR = noise_var / (signal_var + eps);

    W = H_conj ./ (H_mag_sq + NSR);
    F_hat = ifft2(W .* Y);
    restored = real(F_hat);
    restored = max(0, min(1, restored));
end

%% 2. Lucy-Richardson Implementation
function restored = lucy_fourier_restoration(y, psf, iterations)
    y_double = im2double(y);

    if isempty(psf)
        psf = fspecial('gaussian', [5 5], 1); % Default PSF
    end

    otf = psf2otf(psf, size(y_double));
    est = y_double;

    for iter = 1:iterations
        est_fft = fft2(est);
        blurred_est = real(ifft2(est_fft .* otf));
        ratio = y_double ./ (blurred_est + eps);
        correction = real(ifft2(fft2(ratio) .* conj(otf)));
        est = est .* correction;
        est = max(0, est);
    end

    restored = est;
end

%% Trade-offs Discussion:
% 1. Wiener Filter:
%    - Pros: Optimal MSE solution, handles noise well
%    - Cons: Requires noise/signal variance estimates
%    - Trade-off: Balance parameter controls detail vs noise
% 
% 2. Lucy-Richardson:
%    - Pros: Preserves edges, handles non-linearities
%    - Cons: Slow convergence, noise amplification
%    - Trade-off: More iterations improve deconvolution but increase noise

%% Best Practices:
% - Always visualize the magnitude spectrum to identify corrupted frequencies
% - Start with conservative parameters and gradually increase
% - Compare multiple methods using both metrics and visual inspection
% - For your specific case (known frequency corruption), notch filtering 
%   combined with Wiener filtering often works best
